#include <memory>
#include <iostream>

class Resource {};

int main() {
    std::auto_ptr<Resource> p1(new Resource());
    std::cout << "P1 before copy: " << (p1.get() != nullptr) << std::endl; // True

    // Destructive Copy: p1 transfers ownership to p2
    std::auto_ptr<Resource> p2 = p1; 

    std::cout << "P1 after copy: " << (p1.get() != nullptr) << std::endl;  // False (nullptr)
    std::cout << "P2 owns resource: " << (p2.get() != nullptr) << std::endl; // True

    // The resource is deleted only when p2 goes out of scope.
}
